"rg -n 'h1|h2|h3|h4|h5|h6|Brier|0\\.90|80|support|preregister|prereg|reproduc|finite.sample' manuscript reviews novelty.md -g '*.md' -g '*.qmd' -g '*.tex' 2>/dev/null | head -n 250"
];
